#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

static void print_help(void) {
    printf("nsh 0.4.2\n");
    printf("A command-line shell that focuses on performance and productivity.\n\n");
    printf("USAGE:\n    executable [FLAGS] [OPTIONS] [FILE]\n\n");
    printf("FLAGS:\n");
    printf("    -h, --help       Prints help information\n");
    printf("    -l, --login      Behave like a login shell\n");
    printf("        --norc       Don't load nshrc\n");
    printf("        --version    Print the version\n\n");
    printf("OPTIONS:\n");
    printf("    -c <command>        The command to be executed\n\n");
    printf("ARGS:\n    <FILE>    The file to be executed\n");
}

static void print_version(void) {
    printf("0.4.2\n");
}

int run_command(const char *cmd) {
    if (!cmd) return 0;
    int status = system(cmd);
    if (status == -1) return 127;
    if (WIFEXITED(status)) return WEXITSTATUS(status);
    return 1;
}

int run_file(const char *file) {
    if (!file) return 0;
    pid_t pid = fork();
    if (pid < 0) return 127;
    if (pid == 0) {
        execlp("sh", "sh", file, (char*)NULL);
        _exit(127);
    }
    int st = 0;
    if (waitpid(pid, &st, 0) == -1) return 127;
    if (WIFEXITED(st)) return WEXITSTATUS(st);
    return 1;
}

int main(int argc, char **argv) {
    const char *cmd = NULL;
    const char *file = NULL;
    int ignore_norc = 0;
    int login = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], "--version") == 0) {
            print_version();
            return 0;
        } else if (strcmp(argv[i], "-c") == 0) {
            if (i + 1 < argc) {
                cmd = argv[i+1];
                i++;
            }
        } else if (strcmp(argv[i], "--norc") == 0) {
            ignore_norc = 1;
        } else if (strcmp(argv[i], "-l") == 0 || strcmp(argv[i], "--login") == 0) {
            login = 1;
        } else if (argv[i][0] == '-') {
            // unknown option: ignore
        } else {
            if (!file) file = argv[i];
        }
    }

    if (cmd) {
        int rc = run_command(cmd);
        return rc;
    }

    if (file) {
        int rc = run_file(file);
        return rc;
    }

    // No cmd or file: interactive mode
    if (!isatty(STDOUT_FILENO)) {
        printf("nsh: warning: stdout is not a tty\n");
        return 0;
    }

    // Simple interactive REPL
    char *line = NULL;
    size_t len = 0;
    while (1) {
        fputs("nsh> ", stdout);
        fflush(stdout);
        ssize_t r = getline(&line, &len, stdin);
        if (r <= 0) break;
        // remove trailing newline
        if (r > 0 && line[r-1] == '\n') line[r-1] = '\0';
        if (strcmp(line, "exit") == 0) break;
        if (strlen(line) == 0) continue;
        run_command(line);
    }
    free(line);
    return 0;
}
EOF

